// مُولَّد من src/data/adhkar-fadl.json بـ scripts/gen-adhkar-fadl.mjs — لا يُعدَّل يدويًا.
// العنوان = الذكر، النص = «قال ﷺ: …» حرفيًا بلا مصدر ولا راوٍ (المصدر في البيانات فقط).

public struct AdhkarFadlPair: Equatable, Sendable {
    public let id: String
    public let dhikr: String
    public let body: String
}

public enum AdhkarFadl {
    public static let pairs: [AdhkarFadlPair] = [
        .init(id: "fadl-01", dhikr: "سُبْحَانَ اللَّهِ وَبِحَمْدِهِ", body: "قال ﷺ: مَنْ قَالَ سُبْحَانَ اللَّهِ وَبِحَمْدِهِ فِي يَوْمٍ مِائَةَ مَرَّةٍ حُطَّتْ خَطَايَاهُ، وَإِنْ كَانَتْ مِثْلَ زَبَدِ الْبَحْرِ"),
        .init(id: "fadl-02", dhikr: "سُبْحَانَ اللَّهِ وَبِحَمْدِهِ، سُبْحَانَ اللَّهِ الْعَظِيمِ", body: "قال ﷺ: كَلِمَتَانِ خَفِيفَتَانِ عَلَى اللِّسَانِ، ثَقِيلَتَانِ فِي الْمِيزَانِ، حَبِيبَتَانِ إِلَى الرَّحْمَنِ، سُبْحَانَ اللَّهِ الْعَظِيمِ، سُبْحَانَ اللَّهِ وَبِحَمْدِهِ"),
        .init(id: "fadl-03", dhikr: "أَسْتَغْفِرُ اللَّهَ وَأَتُوبُ إِلَيْهِ", body: "قال ﷺ: وَاللَّهِ إِنِّي لأَسْتَغْفِرُ اللَّهَ وَأَتُوبُ إِلَيْهِ فِي الْيَوْمِ أَكْثَرَ مِنْ سَبْعِينَ مَرَّةً"),
        .init(id: "fadl-04", dhikr: "لَا إِلَهَ إِلَّا اللَّهُ", body: "قال ﷺ: مَثَلُ الَّذِي يَذْكُرُ رَبَّهُ وَالَّذِي لاَ يَذْكُرُ مَثَلُ الْحَىِّ وَالْمَيِّتِ"),
        .init(id: "fadl-05", dhikr: "اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ", body: "قال ﷺ: مَنْ صَلَّى عَلَىَّ وَاحِدَةً صَلَّى اللَّهُ عَلَيْهِ عَشْرًا"),
        .init(id: "fadl-06", dhikr: "سُبْحَانَ اللَّهِ، وَالْحَمْدُ لِلَّهِ، وَلَا إِلَهَ إِلَّا اللَّهُ، وَاللَّهُ أَكْبَرُ", body: "قال ﷺ: لأَنْ أَقُولَ سُبْحَانَ اللَّهِ وَالْحَمْدُ لِلَّهِ وَلاَ إِلَهَ إِلاَّ اللَّهُ وَاللَّهُ أَكْبَرُ أَحَبُّ إِلَىَّ مِمَّا طَلَعَتْ عَلَيْهِ الشَّمْسُ"),
        .init(id: "fadl-07", dhikr: "أَسْتَغْفِرُ اللَّهَ", body: "قال ﷺ: يَا أَيُّهَا النَّاسُ تُوبُوا إِلَى اللَّهِ فَإِنِّي أَتُوبُ فِي الْيَوْمِ إِلَيْهِ مِائَةَ مَرَّةٍ"),
        .init(id: "fadl-08", dhikr: "الْحَمْدُ لِلَّهِ", body: "قال ﷺ: إِنَّ اللَّهَ لَيَرْضَى عَنِ الْعَبْدِ أَنْ يَأْكُلَ الأَكْلَةَ فَيَحْمَدَهُ عَلَيْهَا أَوْ يَشْرَبَ الشَّرْبَةَ فَيَحْمَدَهُ عَلَيْهَا"),
        .init(id: "fadl-09", dhikr: "سُبْحَانَ اللَّهِ وَبِحَمْدِهِ", body: "قال ﷺ: إِنَّ أَحَبَّ الْكَلاَمِ إِلَى اللَّهِ سُبْحَانَ اللَّهِ وَبِحَمْدِهِ"),
        .init(id: "fadl-10", dhikr: "سُبْحَانَ اللَّهِ وَبِحَمْدِهِ", body: "قال ﷺ: مَا اصْطَفَى اللَّهُ لِمَلاَئِكَتِهِ أَوْ لِعِبَادِهِ سُبْحَانَ اللَّهِ وَبِحَمْدِهِ"),
        .init(id: "fadl-11", dhikr: "سُبْحَانَ اللَّهِ وَبِحَمْدِهِ", body: "قال ﷺ: مَنْ قَالَ حِينَ يُصْبِحُ وَحِينَ يُمْسِي سُبْحَانَ اللَّهِ وَبِحَمْدِهِ مِائَةَ مَرَّةٍ لَمْ يَأْتِ أَحَدٌ يَوْمَ الْقِيَامَةِ بِأَفْضَلَ مِمَّا جَاءَ بِهِ إِلاَّ أَحَدٌ قَالَ مِثْلَ مَا قَالَ أَوْ زَادَ عَلَيْهِ"),
        .init(id: "fadl-12", dhikr: "سُبْحَانَ اللَّهِ، وَالْحَمْدُ لِلَّهِ، وَلَا إِلَهَ إِلَّا اللَّهُ، وَاللَّهُ أَكْبَرُ", body: "قال ﷺ: أَحَبُّ الْكَلاَمِ إِلَى اللَّهِ أَرْبَعٌ سُبْحَانَ اللَّهِ وَالْحَمْدُ لِلَّهِ وَلاَ إِلَهَ إِلاَّ اللَّهُ وَاللَّهُ أَكْبَرُ لاَ يَضُرُّكَ بَأَيِّهِنَّ بَدَأْتَ"),
    ]

    /// اختيار حتمي يدور على الأزواج: نفس اليوم والخانة ⇒ نفس الزوج.
    public static func pair(dayIndex: Int, slot: Int) -> AdhkarFadlPair {
        let n = pairs.count
        return pairs[(((dayIndex * 3 + slot) % n) + n) % n]
    }
}
